SELECT i.id,i.user_id,i.ca_id FROM mtls_user_identities i JOIN users u ON u.id=i.user_id WHERE NOT i.archived AND i.next_action_at IS NULL AND u.enabled AND (u.expires_at IS NULL OR u.expires_at>(SELECT now FROM cutoff)) AND (u.quota_bytes IS NULL OR u.usage_bytes<u.quota_bytes) AND NOT EXISTS(SELECT 1 FROM background_work w WHERE w.id='mtls-identity:'||i.id AND w.state IN ('queued','running'))
